import XCTest
import Darwin
@testable import ArcaSDK

/// Opt-in host CPU replay; not a device battery/rendering claim.
final class MarketDataPerformanceTests: XCTestCase {
    func testBenchmarkDecodedPricesWithEquityAndSizing() throws {
        try XCTSkipUnless(ProcessInfo.processInfo.environment["ARCA_MARKET_BENCHMARK"] == "1")
        let base = try JSONDecoder().decode(ExchangeState.self, from: Data(#"{"account":{"id":"a1","realmId":"r1","name":"main","createdAt":"2026-09-06","updatedAt":"2026-09-06"},"marginSummary":{"equity":"1000","initialMarginUsed":"150","maintenanceMarginRequired":"0","availableToWithdraw":"950","totalNtlPos":"3000","totalUnrealizedPnl":"0","totalRawUsd":"1000"},"positions":[{"id":"p0","market":"hl:0:C0","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p1","market":"hl:0:C1","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p2","market":"hl:0:C2","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p3","market":"hl:0:C3","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p4","market":"hl:0:C4","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p5","market":"hl:0:C5","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p6","market":"hl:0:C6","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p7","market":"hl:0:C7","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p8","market":"hl:0:C8","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p9","market":"hl:0:C9","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p10","market":"hl:0:C10","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p11","market":"hl:0:C11","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p12","market":"hl:0:C12","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p13","market":"hl:0:C13","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p14","market":"hl:0:C14","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p15","market":"hl:0:C15","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p16","market":"hl:0:C16","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p17","market":"hl:0:C17","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p18","market":"hl:0:C18","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p19","market":"hl:0:C19","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p20","market":"hl:0:C20","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p21","market":"hl:0:C21","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p22","market":"hl:0:C22","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p23","market":"hl:0:C23","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p24","market":"hl:0:C24","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p25","market":"hl:0:C25","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p26","market":"hl:0:C26","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p27","market":"hl:0:C27","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p28","market":"hl:0:C28","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"},{"id":"p29","market":"hl:0:C29","side":"long","size":"1","entryPrice":"100","leverage":20,"marginUsed":"50","positionValue":"1000","unrealizedPnl":"0"}],"openOrders":[]}"#.utf8))
        let subs = Set((0..<30).map { PublicMarketSubscription(market: "hl:0:C\($0)", coin: "C\($0)") })
        let frames = (0..<3000).map { n in Data("""
        {"channel":"bbo","data":{"coin":"C\(n % 30)","time":\(1000 + n),"bbo":[{"px":"\(100 + n / 30)"},{"px":"\(101 + n / 30)"}]}}
        """.utf8) }
        func cpu() -> Double { var t = timespec(); clock_gettime(CLOCK_THREAD_CPUTIME_ID, &t); return Double(t.tv_sec) + Double(t.tv_nsec) / 1e9 }
        func run(_ batch: Int) throws -> (Double, ExchangeState) {
            var mids: [String: String] = [:]; var last = base
            let start = cpu()
            for (i, data) in frames.enumerated() {
                guard case .quote(let market, let price, _) = decodePublicMarketUpdate(try JSONSerialization.jsonObject(with: data) as! [String: Any], subscriptions: subs) else { throw NSError(domain: "decode", code: 1) }
                mids[market] = price
                if (i + 1) % batch == 0 {
                    last = base.revalued(with: mids)
                    XCTAssertNotNil(deriveActiveAssetData(from: last, market: "hl:0:C0", markPx: Double(mids["hl:0:C0"]!)!, leverage: 20, side: .buy))
                }
            }
            return ((cpu() - start) * 1000, last)
        }
        _ = try run(1); _ = try run(30)
        let raw = try run(1), batched = try run(30)
        XCTAssertEqual(raw.1.marginSummary.equity, batched.1.marginSummary.equity)
        print("MARKET_BENCH swift frames=3000 positions=30 raw_cpu_ms=\(raw.0) batched_cpu_ms=\(batched.0) raw_revaluations=3000 batched_revaluations=100 final_equity=\(batched.1.marginSummary.equity)")
    }
}
